/// Create routes for state transitions.
pub fn create_mail_transition_routes(service: Arc<MailService>) -> Router {
    use axum::routing::post;

    Router::new()
        .route("/mails/:id/transitions/smtp_accepted", post(smtp_accepted_transition))
        .route("/mails/:id/transitions/smtp_failed", post(smtp_failed_transition))
        .route("/mails/:id/transitions/inbound_acknowledged", post(inbound_acknowledged_transition))
        .route("/mails/:id/transitions/requeued", post(requeued_transition))
        .route("/mails/:id/transitions/cancelled", post(cancelled_transition))
        .with_state(service)
}
